using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using PortableDev.Core.Model;

namespace PortableDev.Core.Packages;

/// <summary>
/// Renders the <c>manifest.d\pkg-&lt;id&gt;.toml</c> of a package installed from a bucket.
///
/// The generated file is an ordinary tool manifest, so <c>apply</c>, <c>plan</c>,
/// <c>verify</c> and the GUI need no knowledge of Scoop at all.
/// </summary>
public static class GeneratedManifest
{
    /// <summary>File name a generated manifest gets for <paramref name="id"/>.</summary>
    public static string FileName(string id) => "pkg-" + Safe(id) + ".toml";

    public static string Render(ScoopPackage package, IReadOnlyList<string> pathDirs)
    {
        var sb = new StringBuilder();
        sb.AppendLine("# generated by `PortableDev pkg add`; remove it with `PortableDev pkg remove`");
        sb.AppendLine("schema = 1");
        sb.AppendLine();
        sb.AppendLine("[tool]");
        sb.AppendLine("id      = " + Q(package.Id));
        sb.AppendLine("version = " + Q(package.Version));
        sb.AppendLine("title   = " + Q(package.Id + " (Scoop " + package.Bucket + ")"));
        sb.AppendLine("kind    = 'prebuilt'");
        sb.AppendLine("source  = " + Q("scoop:" + package.Bucket + "/" + package.Id));

        var provides = package.Bin
            .Select(Path.GetFileNameWithoutExtension)
            .Where(s => !string.IsNullOrWhiteSpace(s))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();

        if (provides.Count > 0)
            sb.AppendLine("provides = [" + string.Join(", ", provides.Select(Q)) + "]");

        foreach (var dir in pathDirs.Distinct(StringComparer.OrdinalIgnoreCase))
        {
            sb.AppendLine();
            sb.AppendLine("[[path]]");
            sb.AppendLine("dir = " + Q(dir));
        }

        foreach (var persist in package.Persist)
        {
            sb.AppendLine();
            sb.AppendLine("[[persist]]");
            sb.AppendLine("source = " + Q(persist.Source));
            sb.AppendLine("target = " + Q(persist.Target));
        }

        // One cheap self check: the first binary the manifest declares must exist after
        // the install. Anything deeper would duplicate the bucket's job.
        var firstBin = package.Bin.FirstOrDefault();
        if (!string.IsNullOrWhiteSpace(firstBin))
        {
            sb.AppendLine();
            sb.AppendLine("[[verify]]");
            sb.AppendLine("run    = " + Q("cmd.exe /c dir /b \"" + firstBin + "\""));
            sb.AppendLine("expect = " + Q(Path.GetFileName(firstBin)));
        }

        return sb.ToString();
    }

    /// <summary>Directory of a manifest bin entry: "bin\rg.exe" -> "bin", "rg.exe" -> ".".</summary>
    public static string DirOf(string binEntry)
    {
        var normalized = binEntry.Replace('/', '\\').Trim().TrimStart('\\');
        var slash = normalized.LastIndexOf('\\');
        return slash < 0 ? "." : normalized[..slash];
    }

    /// <summary>
    /// A TOML string. Single-quoted (literal) when possible, because these values are
    /// paths full of backslashes and any other form would need escaping.
    /// </summary>
    private static string Q(string value)
    {
        var v = value ?? string.Empty;
        if (!v.Contains('\'')) return "'" + v + "'";

        return "\"" + v.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\"";
    }

    private static string Safe(string id)
    {
        var chars = id.Select(c => char.IsLetterOrDigit(c) || c is '-' or '_' or '.' ? c : '-').ToArray();
        return new string(chars);
    }
}
